import React, { useState } from "react";

function Login({ onLogin }) {
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    if (password === "napping princess") {
      onLogin("personal");
    } else {
      const savedPassword = localStorage.getItem("studyPassword");

      if (savedPassword && password === savedPassword) {
        onLogin("normal");
      } else {
        setError("Wrong password. Try again.");
      }
    }
  };

  const handleCreatePassword = () => {
    const newPassword = prompt("Create your study password:");

    if (newPassword && newPassword.trim() !== "") {
      localStorage.setItem("studyPassword", newPassword);
      setError("Study password created. You can now enter it.");
    }
  };

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="login-icon">📚</div>

        <h1>Welcome to Study Café</h1>

        <p>Enter your password to continue</p>

        <form onSubmit={handleSubmit}>
          <input
            type="password"
            placeholder="Enter password"
            value={password}
            onChange={(e) => {
              setPassword(e.target.value);
              setError("");
            }}
          />

          <button type="submit">Enter</button>
        </form>

        <button
          type="button"
          className="create-password-button"
          onClick={handleCreatePassword}
        >
          Create my study password
        </button>

        {error && <p className="login-message">{error}</p>}
      </div>
    </div>
  );
}

export default Login;