import React, { useState } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";

import Login from "./Login";
import Home from "./Home";
import Physics from "./Physics";
import Chemistry from "./Chemistry";
import Biology from "./Biology";
import PhysicsQuestion from "./data/PhysicsQuestion";

import "./App.css";

function App() {
  const [loginType, setLoginType] = useState(null);

  // Show login screen until a password is entered
  if (!loginType) {
    return <Login onLogin={setLoginType} />;
  }

  const isPersonal = loginType === "personal";

  return (
    <BrowserRouter basename={process.env.PUBLIC_URL}>
      <Routes>
        {/* HOME */}
        <Route
          path="/"
          element={<Home isPersonal={isPersonal} />}
        />

        {/* SUBJECTS */}
        <Route path="/physics" element={<Physics />} />

        <Route
          path="/physics/questions/:index"
          element={<PhysicsQuestion />}
        />

        <Route path="/chemistry" element={<Chemistry />} />

        <Route path="/biology" element={<Biology />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;